  showScheduleMenu = false;
  searchQuery = '';

  /** フィルター */
  filterOneOnOne = true;
  filterMultiple = true;
  filterInternal = true;
  filterActiveOnly = false;
  /** 非表示にした予定も含めて表示するか */
  showHidden = false;

  /** 統計 (monthlyCount は entries から動的算出する getter) */
  /* 修正 No.39 (2026-04-25): 今月の成立件数を固定値 (3) から entries から動的に算出する形に変更 */
  totalCount = 160;

  /** 今月の成立件数 = 当月内に scheduledDate がある「確定」ステータスの件数 */
  get monthlyCount(): number {
    const now = new Date();
    const ym = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    return this.entries.filter(e => {
      if (e.status !== '確定') return false;
      if (!e.scheduledDate) return false;
      return e.scheduledDate.startsWith(ym);
    }).length;
  }

