  constructor(
    private notification: NotificationService,
    private cdr: ChangeDetectorRef,
    private titleService: Title,
    private route: ActivatedRoute,
    /* 修正 No.65 (2026-04-25): 全ページ共通のグローバル予定調整モーダルに統一 */
    private scheduleModal: ScheduleModalService,
  ) {}

  /** 修正 No.65 (2026-04-25): /history の「予定調整する」ボタンをグローバル ScheduleModal に切替 */
  openScheduleModal(): void {
    this.scheduleModal.open();
  }

  ngOnInit(): void {
    this.titleService.setTitle('予定調整履歴 | 日程調整ツール"スケコン"');
    /* ユーザー指示 2026-04-23: グローバル検索から ?q= で受け取った語を反映 */
    this.route.queryParams.subscribe(params => {
      if (params['q']) {
        this.searchQuery = params['q'];
        this.cdr.markForCheck();
      }
    });
  }

  get filteredEntries(): HistoryEntry[] {
    const query = this.searchQuery.trim().toLowerCase();
    return this.entries.filter(e => {
      // 非表示エントリは「非表示を表示」がONのときのみ表示
      if (e.hidden && !this.showHidden) return false;
      if (!this.filterOneOnOne && e.type === '1対1予定調整') return false;
      if (!this.filterMultiple && e.type === '複数人予定調整') return false;
      if (!this.filterInternal && e.type === '社内予定調整') return false;
      if (this.filterActiveOnly && e.status !== '調整中') return false;
      if (query) {
        const searchTarget = `${e.title} ${e.organizer} ${e.type} ${e.status}`.toLowerCase();
        if (!searchTarget.includes(query)) return false;
      }
      return true;
    });
  }

  get hiddenCount(): number {
    return this.entries.filter(e => e.hidden).length;
  }

  getTypeBadgeClass(type: ScheduleType): string {
    switch (type) {
      case '1対1予定調整':
        return 'badge--blue';
      case '複数人予定調整':
        return 'badge--orange';
      case '社内予定調整':
        return 'badge--green';
    }
  }

  getTypeCardClass(type: ScheduleType): string {
    switch (type) {
      case '1対1予定調整':
        return 'entry--blue';
      case '複数人予定調整':
        return 'entry--orange';
      case '社内予定調整':
        return 'entry--green';
    }
  }

  getStatusBadgeClass(status: ScheduleStatus): string {
    switch (status) {
      case '調整中':
        return 'status--pending';
      case '確定':
        return 'status--confirmed';
      case '不成立':
        return 'status--failed';
      case 'キャンセル':
        return 'status--cancelled';
      case '中止':
        return 'status--aborted';
    }
  }

  /** ステータス別のアイコン名 (Material Symbols) */
  getStatusIcon(status: ScheduleStatus): string {
    switch (status) {
      case '確定':     return 'check_circle';
      case '調整中':   return 'schedule';
      case '不成立':   return 'error_outline';
      case 'キャンセル': return 'cancel';
      case '中止':     return 'block';
    }
  }

  onSearch(): void {
    this.cdr.markForCheck();
  }

  onCopyUrl(event: Event, entry: HistoryEntry): void {
    event.stopPropagation();
    navigator.clipboard.writeText(`https://schecon.app/schedule/${entry.id}`);
    this.notification.success('URLをコピーしました');
  }

  onEdit(event: Event, entry: HistoryEntry): void {
    event.stopPropagation();
    this.notification.info(`「${entry.title}」を編集します`);
  }

  onRecreate(event: Event, entry: HistoryEntry): void {
    event.stopPropagation();
    this.notification.info(`「${entry.title}」を再作成します`);
  }

  onDownloadParticipants(event: Event, entry: HistoryEntry): void {
    event.stopPropagation();
    this.notification.info('参加者名簿をダウンロードします');
  }

  /** 予定を削除する（データ・URLは保持、表示のみ非表示） */
  onHide(event: Event, entry: HistoryEntry): void {
    event.stopPropagation();
    entry.hidden = true;
    this.notification.success(`「${entry.title}」を削除しました（データとURLは保持されます）`);
    this.cdr.markForCheck();
  }

  /** 削除した予定を復元 */
  onUnhide(event: Event, entry: HistoryEntry): void {
    event.stopPropagation();
    entry.hidden = false;
    this.notification.info(`「${entry.title}」を復元しました`);
    this.cdr.markForCheck();
  }

  /** 「非表示の予定も表示」トグル */
  toggleShowHidden(): void {
    this.showHidden = !this.showHidden;
    this.cdr.markForCheck();
  }
